// Get session by session number
export const getSessionByNumber = (sessionNumber: number): Session | undefined => {
  return sessions.find(s => s.session === sessionNumber);
};

// Get phrases for a specific session
export const getPhrasesBySession = (sessionNumber: number): Phrase[] => {
  return allPhrases.filter(p => p.session === sessionNumber);
};

// Get all phrases for review
export const getReviewPhrases = (phraseIds: string[]): Phrase[] => {
  return allPhrases.filter(p => phraseIds.includes(p.id));
};
